import { gunzipSync } from "zlib";

const DATA = "";

export type ImportedAdminExamQuestion = {
  id: string;
  domainCategory: string;
  questionText: string;
  questionType: string;
  stage: string;
  grade: string;
  curriculum: string;
  term: string;
  source: string;
  tags: string[];
  unit: string;
  lesson: string;
  section: string;
  difficulty: string;
  skill: string;
  topic: string;
  bloomLevel: string;
  passageText?: string;
  passageHighlightText?: string;
  passageHighlightOccurrence?: number;
  options: string[];
  correctAnswer: string;
  acceptedAnswers?: string[];
  explanation: string;
  points: number;
  timesUsed: number;
  correctCount: number;
  totalAttempts: number;
};

let cached: ImportedAdminExamQuestion[] | null = null;

export function getFirstSecondaryAdminExamQuestions(): ImportedAdminExamQuestion[] {
  if (!cached) {
    const raw = JSON.parse(gunzipSync(Buffer.from(DATA, "base64")).toString("utf8")) as ImportedAdminExamQuestion[];
    cached = raw.map((question) => ({
      ...question,
      timesUsed: 0,
      correctCount: 0,
      totalAttempts: 0,
    }));
  }
  return cached;
}

export const FIRST_SECONDARY_ADMIN_EXAM_QUESTION_COUNT = 341;
